const fs=require('fs'),vm=require('vm'),path=require('path'),crypto=require('crypto');
const root=process.argv[2]||path.resolve(__dirname,'../../..'),out=__dirname,c={TextDecoder};c.window=c;vm.createContext(c);vm.runInContext(fs.readFileSync(path.join(root,'src/mvt.js'),'utf8'),c);
const area=r=>r.reduce((s,a,i)=>{const b=r[(i+1)%r.length];return s+a.x*b.y-a.y*b.x},0)/2;
const candidates=[],tiles=[];
for(const f of fs.readdirSync(path.join(root,'test/fixtures')).filter(f=>/^275[345]_556[567]\.pbf$/.test(f))){const bytes=fs.readFileSync(path.join(root,'test/fixtures',f)),[tx,ty]=f.replace('.pbf','').split('_').map(Number),layers=c.MVT.decodeTile(new Uint8Array(bytes)),layer=layers.find(l=>l.name==='building'),extent=layer.extent||4096;const tile={path:'test/fixtures/'+f,sha256:crypto.createHash('sha256').update(bytes).digest('hex'),tx,ty,z:14,extent};tiles.push(tile);for(const feature of layer.features)for(let ri=0;ri<feature.geom.length;ri++){const raw=feature.geom[ri],r=raw.slice(0,-1),A=area(r);if(A<=0||r.length<6||r.some(p=>p.x<=0||p.y<=0||p.x>=extent||p.y>=extent))continue;const cx=r.reduce((s,p)=>s+p.x,0)/r.length,cy=r.reduce((s,p)=>s+p.y,0)/r.length,lon=(tx+cx/extent)/2**14*360-180,lat=Math.atan(Math.sinh(Math.PI*(1-2*(ty+cy/extent)/2**14)))*180/Math.PI,m=40075016.686*Math.cos(lat*Math.PI/180)/2**14/extent;const minX=Math.min(...r.map(p=>p.x)),minY=Math.min(...r.map(p=>p.y)),w=Math.max(...r.map(p=>p.x))-minX,h=Math.max(...r.map(p=>p.y))-minY;let reflex=0,angled=0,minEdge=Infinity;for(let i=0;i<r.length;i++){const a=r[(i+r.length-1)%r.length],b=r[i],d=r[(i+1)%r.length],cross=(b.x-a.x)*(d.y-b.y)-(b.y-a.y)*(d.x-b.x);if(cross<0)reflex++;if(b.x!==d.x&&b.y!==d.y)angled++;minEdge=Math.min(minEdge,Math.hypot(b.x-d.x,b.y-d.y));}if(reflex<2||A*m*m<60||A*m*m>18000)continue;candidates.push({id:`z14-${tx}-${ty}-feature${feature.id}-ring${ri}`,tile:tile.path,tx,ty,z:14,extent,mvtFeatureId:feature.id,ringIndex:ri,tags:feature.tags,centroid:{lon,lat},metrics:{vertices:r.length,reflex,angledEdges:angled,areaM2:A*m*m,bboxFill:A/(w*h),minEdgeM:minEdge*m,widthM:w*m,depthM:h*m},rawRing:raw,localMeters:r.map(p=>({x:(p.x-minX)*m,y:(p.y-minY)*m})),metersPerMvtUnit:m});}}
const selected=[],used=new Set();function pick(label,filter,score,n){for(const b of candidates.filter(filter).sort((a,b)=>score(b)-score(a))){if(used.has(b.id)||selected.some(a=>Math.hypot(a.centroid.lon-b.centroid.lon,a.centroid.lat-b.centroid.lat)<.0001))continue;used.add(b.id);selected.push({...b,selection:label});if(--n===0)break;}}
pick('most articulated concave outline',b=>b.metrics.vertices<=100,b=>b.metrics.reflex,3);pick('low-fill narrow wings',b=>b.metrics.bboxFill<.6&&b.metrics.vertices<=50,b=>1-b.metrics.bboxFill,3);pick('angled edges with concave corners',b=>b.metrics.vertices>=10&&b.metrics.vertices<=40,b=>b.metrics.angledEdges/b.metrics.vertices,3);pick('small articulated residence',b=>b.metrics.areaM2<400&&b.metrics.vertices<=30,b=>b.metrics.reflex,3);
const fixture={provenance:{description:'Unmodified closed exterior rings decoded by production MVT.decodeTile from repository Kelowna OpenFreeMap z14 fixtures. OpenFreeMap building features combine many OSM-derived rings: feature IDs below are MVT IDs, not asserted individual OSM way IDs. Raw vertex arrays retained exactly, including closing vertex. localMeters only translates/scales, with no snapping, simplification, orthogonalization or reshaping.',sourceRoot:'repository root',decoder:'src/mvt.js',tiles,candidateCount:candidates.length},buildings:selected};fs.writeFileSync(path.join(out,'fixtures.json'),JSON.stringify(fixture,null,2)+'\n');console.log(JSON.stringify(selected.map(b=>({id:b.id,selection:b.selection,...b.metrics})),null,2));
